//! Fresh QA FT compiler using the SAME frozen SDK/compiler and Cargo lock.
//! Do not pass token event IR through the market-specific height rebaser.
use anyhow::{ensure,Result};use std::{env,fs,path::Path};use sha2::{Digest,Sha256};
fn main()->Result<()>{let a=env::args().collect::<Vec<_>>();ensure!(a.len()==3,"SOURCE FRESH_OUTPUT");let source=fs::read(&a[1])?;let text=std::str::from_utf8(&source)?;let artifact=psy_compiler::compile(text)?;ensure!(artifact.state_tree_height()==31,"U124 FT layout height");psy_template_u124_markets::layout_preflight::verify_abi_layout(&artifact.abi_to_json()?)?;let out=Path::new(&a[2]);fs::create_dir(out)?;fs::write(out.join("compilation_artifact.json"),artifact.to_compilation_artifact_json()?)?;fs::write(out.join("abi.json"),artifact.abi_to_json()?)?;fs::write(out.join("source-sha256.txt"),format!("{:x}\n",Sha256::digest(&source)))?;println!("Compiled {} FT methods with frozen SDK; not deployed or UPS verified",artifact.method_count());Ok(())}
